      "Cepheler: Taarruz Cepheleri: Kafkas ve Kanal (\"K\" harfiyle başlar). Savunma Cepheleri: Çanakkale, Suriye-Filistin, Irak, Hicaz-Yemen. Yardım Cepheleri: Galiçya, Romanya, Makedonya (sınırlar dışı)."
