      "Tehlikeli Maddeler: 7. Madde: İtilaf Devletleri güvenliklerini tehdit eden herhangi bir stratejik noktayı işgal edebilecektir (Tüm Anadolu'yu işgale açık hale getiren en tehlikeli maddedir). 24. Madde: Vilâyet-i Sitte'de (6 Doğu ili: Erzurum, Van, Bitlis, Diyarbakır, Elazığ, Sivas) karışıklık çıkarsa buralar işgal edilecektir (Doğu Anadolu'da bir Ermeni Devleti kurma amacı güder).",
      "Tutumlar: İstanbul Hükümeti (Damat Ferit): Teslimiyetçi, pasif ve işgallere sessiz kalarak İtilafların isteklerini yerine getirme yanlısıdır. Mustafa Kemal: Bağımsızlıkçı, vatanın bölünmezliğine inanan ve milleti örgütleyen kararlı tutum (\"Geldikleri gibi giderler\"). Türk Halkı: İşgallere karşı önce mitinglerle tepki göstermiş, ardından Kuvâ-yı Millîye silahlı birliklerini ve Müdafaa-i Hukuk cemiyetlerini kurarak direnişe geçmiştir."
